mapper.insert:

    SELECT
        'RESK'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(RECRUIT_SKILL_CODE), LENGTH('RESK' ) + 1)), 0) + 1, 6, '0')
    FROM RECRUITMENT_SKILL

	INSERT INTO RECRUITMENT_SKILL (
		RECRUIT_SKILL_CODE
		, RECRUITMENT_NO
		, RECRUIT_SKILL_NAME
	) VALUES (
		#{recruitSkillCode}
		, #{recruitmentNo}
		, #{recruitSkillName}
	)

mapper.update:
UPDATE RECRUITMENT_SKILL SET 
	RECRUIT_SKILL_NAME = #{recruitSkillName} 
WHERE RECRUIT_SKILL_CODE = #{recruitSkillCode}

mapper.delete:
UPDATE RECRUITMENT_SKILL SET
	RECRUIT_SKILL_DEL_DATE = SYSDATE 
WHERE RECRUIT_SKILL_CODE = #{recruitSkillCode}
